import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.7R1OEGYz.js";const u=JSON.parse('{"title":"Git integrations","description":"","frontmatter":{},"headers":[],"relativePath":"git.md","filePath":"git.md","lastUpdated":1785866144000}'),n={name:"git.md"};function o(r,e,p,h,l,d){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="git-integrations" tabindex="-1">Git integrations <a class="header-anchor" href="#git-integrations" aria-label="Permalink to &quot;Git integrations&quot;">​</a></h1><p>There are two ways to give a session access to your repositories. The manual one works out of the box; the OAuth one is nicer for more than one user.</p><h2 id="option-1-—-a-token-or-ssh-key" tabindex="-1">Option 1 — a token or SSH key <a class="header-anchor" href="#option-1-—-a-token-or-ssh-key" aria-label="Permalink to &quot;Option 1 — a token or SSH key&quot;">​</a></h2><p>Under <strong>Settings → Credentials</strong>, store an SSH private key, or a GitLab/GitHub token, plus optionally <code>known_hosts</code> for the server. Values are written to a per-user Kubernetes secret, never kept in the database, and never returned by the API.</p><p>Inside the session the token is wired up as a git credential helper for HTTPS remotes, and exported as <code>GITLAB_TOKEN</code> so <code>glab</code> works. A GitLab token needs <code>write_repository</code> for clone and push, or <code>api</code> if you want <code>glab</code> to open merge requests.</p><h2 id="option-2-—-connect-an-account-over-oauth" tabindex="-1">Option 2 — connect an account over OAuth <a class="header-anchor" href="#option-2-—-connect-an-account-over-oauth" aria-label="Permalink to &quot;Option 2 — connect an account over OAuth&quot;">​</a></h2><p>Users click <strong>Connect</strong> on the Account page and authorize once; sessions then clone and push without anyone handling a token. Tokens are stored in a per-user Kubernetes secret and refreshed automatically.</p><h3 id="your-callback-url" tabindex="-1">Your callback URL <a class="header-anchor" href="#your-callback-url" aria-label="Permalink to &quot;Your callback URL&quot;">​</a></h3><p>Register this as the redirect URI at the provider:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://&lt;your-host&gt;/api/git/callback/&lt;provider-id&gt;</span></span></code></pre></div><p>The last path segment is the <code>id</code> you give the provider in the values file — so with <code>id: gitlab</code> and host <code>hub.your-org.example</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://hub.your-org.example/api/git/callback/gitlab</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Not the same as your login callback</p><p>OIDC <strong>login</strong> uses <code>https://&lt;your-host&gt;/auth/callback</code>. That is a different thing from Git account connections. Registering one where the other belongs is the most common mistake here.</p></div><p>The URL is built from the configured frontend origin, not from the incoming request, so it stays correct behind a proxy.</p><h3 id="configure-the-provider" tabindex="-1">Configure the provider <a class="header-anchor" href="#configure-the-provider" aria-label="Permalink to &quot;Configure the provider&quot;">​</a></h3><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">git</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # Signs the OAuth &quot;state&quot; parameter. Random, 32+ characters, and stable across</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # restarts and replicas — a generated-per-start key breaks the flow on every restart.</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  stateKey</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;random 32+ chars&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  providers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">gitlab</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">gitlab</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # github | gitlab</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      displayName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">GitLab</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      baseUrl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # e.g. https://gitlab.example.com for self-hosted</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      clientId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;application id&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      clientSecret</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;secret&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      scopes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # empty = sensible defaults, see below</span></span></code></pre></div><p>Apply it with <code>helm upgrade -f</code>, and the <strong>Connect</strong> buttons appear on the Account page. The UI only shows that section when at least one provider has both a client id and a secret.</p><h3 id="at-the-provider" tabindex="-1">At the provider <a class="header-anchor" href="#at-the-provider" aria-label="Permalink to &quot;At the provider&quot;">​</a></h3><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-5CyS8" id="tab-m5jtLRt" checked><label data-title="GitLab" for="tab-m5jtLRt">GitLab</label><input type="radio" name="group-5CyS8" id="tab-UPYKxkv"><label data-title="GitHub" for="tab-UPYKxkv">GitHub</label></div><div class="blocks"><div class="language-text vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User Settings → Applications → Add new application</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Redirect URI:  https://&lt;your-host&gt;/api/git/callback/gitlab</span></span>
<span class="line"><span>Confidential:  yes — the token exchange sends a client secret</span></span>
<span class="line"><span>Scopes:        tick &quot;api&quot; and &quot;read_user&quot;</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Settings → Developer settings → OAuth Apps → New OAuth App</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Authorization callback URL:  https://&lt;your-host&gt;/api/git/callback/github</span></span>
<span class="line"><span>Scopes:                      nothing to tick — the request decides</span></span></code></pre></div></div></div><div class="warning custom-block"><p class="custom-block-title">GitLab rejects scopes it was not registered with</p><p>GitLab pins the allowed scopes <strong>when you create the application</strong>, and refuses anything beyond them:</p><blockquote><p>The requested scope is invalid, unknown, or malformed.</p></blockquote><p>If you see that on the GitLab consent screen, the application is missing a tick — not your configuration. Open the application in GitLab, tick <code>api</code> and <code>read_user</code>, save, and try again. Whatever you tick has to be a superset of what the values file requests.</p><p>GitHub works the other way round: an OAuth App declares no scopes up front, so the authorize request alone decides and this failure mode does not exist there.</p></div><p>Leaving <code>scopes</code> empty uses the provider defaults — <code>api read_user</code> for GitLab, <code>repo read:user</code> for GitHub — which is enough to browse repositories, clone, and push.</p><h3 id="scopes-for-agents-that-maintain-their-own-repository" tabindex="-1">Scopes for agents that maintain their own repository <a class="header-anchor" href="#scopes-for-agents-that-maintain-their-own-repository" aria-label="Permalink to &quot;Scopes for agents that maintain their own repository&quot;">​</a></h3><p>If you want sessions to open pull requests, cut releases, and read CI results with <code>gh</code>, the GitHub defaults are not quite enough:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">scopes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;repo workflow read:org read:user&quot;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Scope</th><th>Why</th></tr></thead><tbody><tr><td><code>repo</code></td><td>Commits, pushes, releases, and reading Actions runs — all repo-scoped</td></tr><tr><td><code>workflow</code></td><td><strong>Required to push any commit that touches <code>.github/workflows/</code>.</strong> Without it GitHub rejects the push outright, so an agent cannot change its own CI</td></tr><tr><td><code>read:org</code></td><td>Lets <code>gh</code> see organisation repositories</td></tr><tr><td><code>read:user</code></td><td>Identifies the account; part of the default</td></tr></tbody></table><p>The narrower GitLab equivalent, if you would rather not grant the broad <code>api</code> scope, is <code>read_api read_repository write_repository read_user</code> — tick exactly those in the application too.</p><p>Changing scopes later does not affect accounts that are already connected: existing tokens keep the scopes they were issued with. Disconnect and reconnect to pick up new ones.</p><h3 id="making-gh-and-glab-work-inside-a-session" tabindex="-1">Making <code>gh</code> and <code>glab</code> work inside a session <a class="header-anchor" href="#making-gh-and-glab-work-inside-a-session" aria-label="Permalink to &quot;Making \`gh\` and \`glab\` work inside a session&quot;">​</a></h3><p>Sessions get their CLI credentials from the git credential store, which is assembled from the <strong>providers of the repositories attached to that session</strong>. So a session only has an authenticated <code>gh</code> if at least one of its repositories was chosen through the repository picker — picking it there is what records the provider. A repository typed in as a plain URL has no provider attached, and <code>gh</code> will be unauthenticated even though the account is connected.</p><h3 id="self-hosted-instances" tabindex="-1">Self-hosted instances <a class="header-anchor" href="#self-hosted-instances" aria-label="Permalink to &quot;Self-hosted instances&quot;">​</a></h3><p>Set <code>baseUrl</code> to the instance root, for example <code>https://gitlab.example.com</code>. The authorize, token, and API endpoints are derived from it.</p><h2 id="network-access" tabindex="-1">Network access <a class="header-anchor" href="#network-access" aria-label="Permalink to &quot;Network access&quot;">​</a></h2><p>No extra egress configuration is needed for gitlab.com, github.com, or a self-hosted instance on 443 or 22 — agent pods may already reach those ports. Only a Git server on a non-standard port needs an entry in <code>agent.extraEgressPorts</code>.</p>`,33)])])}const g=t(n,[["render",o]]);export{u as __pageData,g as default};
